@startuml

class Researcher {
  + name : string
  + surname : string
  + available : boolean
}

class SeniorResearcher extends Researcher {}

class JuniorResearcher extends Researcher {}

class Team {
  + name : string
}

class Project {
  + name : string
}

class Area {
  + name : string
}

class AreaManager {
  + name : string
  + surname : string
}

SeniorResearcher "1" -- "1" Team : Leads
Team "1" *-- "1..*" JuniorResearcher : includes
Area "1" -- "1" AreaManager : has
Area "1" -- "*" Team : groups
Team -- "1" Project : carries out

@enduml

